/* HEXA BATTLEGROUNDS setup — PART 88 OF 94. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('battle-loadout-44', 'loadout', 'battle', 'Loadout Math', 'game', 2, array['duel_pistol','duel_smg','duel_sniper']::text[], 'A rival squad is pinned behind a car. How many hits does it take to knock them out with the gun you choose?', '{"scout":{"title":"Through the scope","body":"Rival squad: 90 HP + 0 shield\nWearing: no vest","big":true},"decoder":{"title":"Gun table (damage per hit)","body":"Pistol         3\nSMG            3\nShotgun        9\nAssault Rifle  4\nSniper         16\n\nVest 1 / 2 / 3 cuts every hit by 10 / 20 / 30 %, rounded to the nearest whole number (at least 1).","mono":true},"intel":{"title":"In your hands","body":"You are carrying: Pistol, Shotgun, Assault Rifle.\nThe captain says: use the Assault Rifle."}}'::jsonb, '[{"label":"Hits needed","accept":["23"]}]'::jsonb, false, 3, 90, 'Damage per hit after the vest, then divide HP + shield by it and round up.', 'Assault Rifle 4 → 4 per hit through vest 0; 90 ÷ 4 → 23', null, 25, 'published'), ('battle-loadout-45', 'loadout', 'battle', 'Loadout Math', 'game', 2, array['duel_pistol','duel_smg','duel_sniper']::text[], 'A rival squad is pinned behind a car. How many hits does it take to knock them out with the gun you choose?', '{"scout":{"title":"Through the scope","body":"Rival squad: 90 HP + 20 shield\nWearing: Vest level 1","big":true},"decoder":{"title":"Gun table (damage per hit)","body":"Pistol         3\nSMG            3\nShotgun        9\nAssault Rifle  4\nSniper         16\n\nVest 1 / 2 / 3 cuts every hit by 10 / 20 / 30 %, rounded to the nearest whole number (at least 1).","mono":true},"intel":{"title":"In your hands","body":"You are carrying: Sniper, Pistol, Shotgun.\nThe captain says: use the Pistol."}}'::jsonb, '[{"label":"Hits needed","accept":["37"]}]'::jsonb, false, 3, 90, 'Damage per hit after the vest, then divide HP + shield by it and round up.', 'Pistol 3 → 3 per hit through vest 1; 110 ÷ 3 → 37', null, 25, 'published'), ('mission-zonerun-0', 'zonerun', 'mission', 'Zone Run', 'maths', 2, array['public','terrace','gate','observation','any']::text[], 'The gas wall is coming. Do you make it into the safe zone, and is it faster to run or to take the buggy?', '{"scout":{"title":"Range finder","body":"Safe zone edge: 360 m away.\nYour buggy: 60 m behind you (you must run to it first).","big":true},"decoder":{"title":"Speeds","body":"Running: 5 m/s\nBuggy: 18 m/s\nRound every leg UP to whole seconds.","mono":true},"intel":{"title":"Zone timer","body":"The wall reaches you in 45 seconds."}}'::jsonb, '[{"label":"RUN or BUGGY (the faster one)","accept":["BUGGY"]},{"label":"Do you make it? YES / NO","accept":["YES"]}]'::jsonb, false, 3, 200, 'Running time = distance ÷ run speed. Buggy time = time to reach the buggy + distance ÷ buggy speed.', 'run 72s, buggy 32s → BUGGY; 32s vs 45s → YES', null, 25, 'published'), ('mission-zonerun-1', 'zonerun', 'mission', 'Zone Run', 'maths', 2, array['public','terrace','gate','observation','any']::text[], 'The gas wall is coming. Do you make it into the safe zone, and is it faster to run or to take the buggy?', '{"scout":{"title":"Range finder","body":"Safe zone edge: 270 m away.\nYour buggy: 60 m behind you (you must run to it first).","big":true},"decoder":{"title":"Speeds","body":"Running: 6 m/s\nBuggy: 18 m/s\nRound every leg UP to whole seconds.","mono":true},"intel":{"title":"Zone timer","body":"The wall reaches you in 47 seconds."}}'::jsonb, '[{"label":"RUN or BUGGY (the faster one)","accept":["BUGGY"]},{"label":"Do you make it? YES / NO","accept":["YES"]}]'::jsonb, false, 3, 200, 'Running time = distance ÷ run speed. Buggy time = time to reach the buggy + distance ÷ buggy speed.', 'run 45s, buggy 25s → BUGGY; 25s vs 47s → YES', null, 25, 'published'), ('mission-zonerun-2', 'zonerun', 'mission', 'Zone Run', 'maths', 2, array['public','terrace','gate','observation','any']::text[], 'The gas wall is coming. Do you make it into the safe zone, and is it faster to run or to take the buggy?', '{"scout":{"title":"Range finder","body":"Safe zone edge: 170 m away.\nYour buggy: 60 m behind you (you must run to it first).","big":true},"decoder":{"title":"Speeds","body":"Running: 6 m/s\nBuggy: 15 m/s\nRound every leg UP to whole seconds.","mono":true},"intel":{"title":"Zone timer","body":"The wall reaches you in 61 seconds."}}'::jsonb, '[{"label":"RUN or BUGGY (the faster one)","accept":["BUGGY"]},{"label":"Do you make it? YES / NO","accept":["YES"]}]'::jsonb, false, 3, 200, 'Running time = distance ÷ run speed. Buggy time = time to reach the buggy + distance ÷ buggy speed.', 'run 29s, buggy 22s → BUGGY; 22s vs 61s → YES', null, 25, 'published'), ('mission-zonerun-3', 'zonerun', 'mission', 'Zone Run', 'maths', 2, array['public','terrace','gate','observation','any']::text[], 'The gas wall is coming. Do you make it into the safe zone, and is it faster to run or to take the buggy?', '{"scout":{"title":"Range finder","body":"Safe zone edge: 330 m away.\nYour buggy: 60 m behind you (you must run to it first).","big":true},"decoder":{"title":"Speeds","body":"Running: 5 m/s\nBuggy: 15 m/s\nRound every leg UP to whole seconds.","mono":true},"intel":{"title":"Zone timer","body":"The wall reaches you in 30 seconds."}}'::jsonb, '[{"label":"RUN or BUGGY (the faster one)","accept":["BUGGY"]},{"label":"Do you make it? YES / NO","accept":["NO"]}]'::jsonb, false, 3, 200, 'Running time = distance ÷ run speed. Buggy time = time to reach the buggy + distance ÷ buggy speed.', 'run 66s, buggy 34s → BUGGY; 34s vs 30s → NO', null, 25, 'published'), ('mission-zonerun-4', 'zonerun', 'mission', 'Zone Run', 'maths', 2, array['public','terrace','gate','observation','any']::text[], 'The gas wall is coming. Do you make it into the safe zone, and 